<template>
  <section
    id="begin-with-what-you-want-to-understand"
    class="about-ai-entry"
    :class="{ 'has-interactive-paths': interactive }"
  >
    <div v-if="interactive" class="home-ai-paths" :class="[active ? `active-${active}` : '', { 'opens-up': active && upward }]" @pointerleave="hovered = ''">
      <div v-for="item in entries" :key="item.key" class="home-ai-slot" :class="{ 'is-active': active === item.key }">
      <button type="button" class="home-ai-path" :class="{ 'is-active': active === item.key }" :aria-label="item.accessible" @pointerenter="enter(item.key, $event)" @focus="focus(item.key, $event)" @blur="focused = ''" @click="openEntry(item.key)">
        <span class="home-ai-label"><i :class="item.icon" aria-hidden="true" /><AiAskTerm v-if="item.key === 'ask'" /><AiViewTerm v-else-if="item.key === 'view'" /><span v-else>Search</span></span>
        <strong class="home-ai-title">{{ item.title }}</strong>
        <span class="home-ai-copy">{{ item.copy }}</span>
        <span class="home-ai-scene"><HomeEntryScene :kind="item.key" :active="active === item.key" /></span>
        <span class="home-ai-action"><template v-if="item.key === 'view'">Compose a <AiViewTerm /></template><template v-else>{{ item.action }}</template><ArrowUpRightIcon /></span>
      </button>
      </div>
    </div>
    <div v-else class="about-ai-paths">
      <button type="button" class="about-ai-path" @click="openSearchPalette">
        <span class="about-ai-path-label"><i class="fa fa-search" aria-hidden="true"></i> Search</span>
        <strong>Go straight to the source</strong>
        <span class="about-ai-path-copy">Search across the whole site, see the relevant excerpt in context, and open the exact place it came from.</span>
        <span class="about-ai-path-action">Search the site <ArrowUpRightIcon /></span>
      </button>

      <button type="button" class="about-ai-path" @click="openAskPalette">
        <span class="about-ai-path-label"><i class="far fa-comment-dots" aria-hidden="true"></i><AiAskTerm /></span>
        <strong>Ask what you want to know</strong>
        <span class="about-ai-path-copy">Ask a question about Henry and get a direct answer grounded in the site, with citations to the relevant sources.</span>
        <span class="about-ai-path-action">Ask a question <ArrowUpRightIcon /></span>
      </button>

      <button type="button" class="about-ai-path" @click="openViewPalette">
        <span class="about-ai-path-label"><i class="fas fa-cube" aria-hidden="true"></i><AiViewTerm /></span>
        <strong>See Henry through your own lens</strong>
        <span class="about-ai-path-copy">Start with a theme, question, or perspective. AI brings together relevant material from across the site into a focused View.</span>
        <span class="about-ai-path-action">Compose a <AiViewTerm /> <ArrowUpRightIcon /></span>
      </button>
    </div>
  </section>
</template>

<script>
import AiAskTerm from './ui/AiAskTerm.vue';
import AiViewTerm from './ui/AiViewTerm.vue';
import ArrowUpRightIcon from './ui/ArrowUpRightIcon.vue';
import HomeEntryScene from './ui/HomeEntryScene.vue';
import { supportsDesktopHover, watchDesktopHover } from '../utils/desktopHover';

export default {
  name: 'AboutAiEntry',
  components: { AiAskTerm, AiViewTerm, ArrowUpRightIcon, HomeEntryScene },
  props: { interactive: Boolean },
  data: () => ({
    hovered: '', focused: '', upward: false,
    entries: [
      { key: 'search', icon: 'fa fa-search', title: 'Go straight to the source', copy: 'Find a passage and open its exact place in the site.', action: 'Search the site', accessible: 'Search the site for original material' },
      { key: 'ask', icon: 'far fa-comment-dots', title: 'Ask what you want to know', copy: 'Get a direct answer with the original sources alongside it.', action: 'Ask a question', accessible: 'Ask a question about Henry' },
      { key: 'view', icon: 'fas fa-cube', title: 'See Henry through your own lens', copy: 'Bring related material together into a focused reading path.', action: 'Compose a View', accessible: 'Compose a focused View' },
    ],
  }),
  computed: { active() { return this.hovered || this.focused; } },
  mounted() { this._stopHover = watchDesktopHover(enabled => { if (!enabled) { this.hovered = ''; this.focused = ''; } }); },
  beforeUnmount() { this._stopHover?.(); },
  methods: {
    place(event) { this.upward = event.currentTarget.closest('.home-ai-slot').getBoundingClientRect().bottom + 76 > window.innerHeight - 16; },
    enter(key, event) { if (event.pointerType !== 'touch' && supportsDesktopHover()) { this.place(event); this.hovered = key; } },
    focus(key, event) { if (event.target.matches(':focus-visible') && supportsDesktopHover()) { this.place(event); this.focused = key; } },
    openEntry(key) {
      this.hovered = '';
      this.focused = '';
      ({ search: this.openSearchPalette, ask: this.openAskPalette, view: this.openViewPalette })[key]();
    },
    openSearchPalette() {
      window.dispatchEvent(new CustomEvent('open-site-search'));
    },
    openAskPalette() {
      window.dispatchEvent(new CustomEvent('open-site-ask'));
    },
    openViewPalette() {
      window.dispatchEvent(new CustomEvent('open-site-view'));
    },
  },
};
</script>

