<template>
  <div class="ops-lab browser-lab">
    <div class="lab-caption"><span class="lab-overline">Browser Control</span><span>A ticket, a new tab, and a small conversation.</span></div>
    <div class="browser-workbench" :class="{ 'has-task-tab': tabOpened }">
      <section ref="dashboard" class="ticket-desk" aria-label="Service desk dashboard">
        <div class="window-chrome"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>service-desk.example / tickets</span></div>
        <div class="dashboard-body">
          <div class="desk-heading"><span class="desk-symbol" aria-hidden="true"><ArrowUpRightIcon /></span><span>Service desk</span><span class="dashboard-avatar">HW</span></div>
          <div class="queue-heading"><strong>Your queue</strong><span>{{ tickets.length - Object.keys(resolvedTickets).length }} open <span aria-hidden="true">·</span> {{ Object.keys(resolvedTickets).length }} resolved</span></div>
          <div class="ticket-queue" aria-label="Choose a ticket"><button v-for="ticket in tickets" :key="ticket.id" type="button" :disabled="active" :aria-pressed="selectedTicket === ticket.id" @click="chooseTicket(ticket.id)"><span class="queue-ticket-id">{{ ticket.id }}<span>{{ resolvedTickets[ticket.id] ? 'Resolved' : 'Open' }}</span></span><strong>{{ ticket.title }}</strong><span class="queue-ticket-preview">{{ ticket.message }}</span></button></div>
          <div class="opened-ticket"><div class="ticket-detail-heading"><span>{{ currentTicket.id }}</span><span class="ticket-status" :class="{ complete: !!ticketRecord }">{{ ticketStatus }}</span></div><p class="ticket-message">“{{ currentTicket.message }}”</p>
            <div v-if="ticketRecord" class="ticket-resolution"><span class="notebook-label"><span aria-hidden="true"><SiteIcon name="check" /></span>Resolved {{ ticketRecord.completedAt }}</span><p>{{ ticketRecord.result }}</p><span>The application confirmed the change.</span></div>
            <button v-if="!active && !ticketRecord" type="button" class="lab-primary launch-agent" @click="begin"><span aria-hidden="true"><SiteIcon name="spark" /></span>{{ status === 'idle' ? 'Hand this ticket to AI' : 'Try this ticket again' }}<span aria-hidden="true"><ArrowUpRightIcon /></span></button>
            <div v-else-if="active" class="dashboard-handoff"><span aria-hidden="true"><ArrowUpRightIcon /></span><p>The task is open in its own tab.<span>Your ticket stays here as the work continues.</span></p></div>
          </div>
          <div v-if="visibleHistory.length" class="agent-notebook"><div class="notebook-label">{{ ticketRecord ? 'Execution record' : 'Latest activity' }}<span v-if="ticketRecord" class="record-count">{{ visibleHistory.length }} events</span></div><TransitionGroup name="activity" tag="ol" class="activity-history" :class="{ 'execution-record': !!ticketRecord }"><li v-for="entry in visibleHistory" :key="`${selectedTicket}-${entry.id}`"><time>{{ entry.time }}</time><div><span class="history-actor">{{ entry.actor }}</span><span>{{ entry.text }}</span></div></li></TransitionGroup></div>
        </div>
      </section>

      <Transition name="task-tab"><div v-if="tabOpened" ref="browser" class="application-stage">
        <div class="separate-tab-label"><span aria-hidden="true"><ArrowUpRightIcon /></span>Opened in a new application tab</div>
        <section class="application-window" aria-label="The application AI operates">
        <div class="window-chrome"><span class="window-dots" aria-hidden="true"><i></i><i></i><i></i></span><span>{{ config.address }}</span><span class="window-lock" aria-hidden="true"><SiteIcon name="window" /></span></div>
        <div class="application-heading"><span class="app-monogram" aria-hidden="true">{{ type === 'access' ? 'W' : 'E' }}</span><strong>{{ config.app }}</strong><span class="app-avatar">HW</span></div>
        <div ref="canvas" class="application-canvas">
          <Transition name="app-surface" mode="out-in">
            <div v-if="status === 'complete'" key="complete" class="application-success">
              <span class="success-seal" aria-hidden="true"><SiteIcon name="check" /></span>
              <p>{{ type === 'access' ? 'Access granted' : 'Request received' }}</p>
              <span>{{ resultSentence }}</span>
              <div class="success-receipt"><span>Recorded with the ticket</span><strong>Completed</strong></div>
              <button type="button" class="lab-secondary" @click="viewRecord">View ticket record <ArrowUpRightIcon /></button>
            </div>
            <div v-else-if="status === 'auth'" key="auth" class="application-sign-in">
              <span class="sign-in-mark" aria-hidden="true"><SiteIcon name="corner-arrow" /></span><p>Confirm it’s you</p>
              <span>Your browser session needs a sign-in before the agent can continue.</span>
              <button type="button" class="lab-primary" @click="completeSignIn">Complete sign-in</button>
              <small>The agent will pick up from this page.</small>
            </div>
            <div v-else-if="opened" key="form" class="application-form">
              <p class="app-breadcrumb">{{ type === 'access' ? 'People / New access' : 'Equipment / New request' }}</p>
              <p class="app-form-title">{{ type === 'access' ? 'Add a workspace member' : 'Prepare a new starter' }}</p>
              <label class="app-field" :class="{ targeted: targetField === 'person' && status === 'running' }">Colleague<input ref="person" :value="form.person" aria-label="Application colleague" :readonly="status !== 'manual'" placeholder="Find a colleague…" @input="editField('person', $event.target.value)"></label>
              <label class="app-field" :class="{ targeted: targetField === 'target' && status === 'running' }">{{ config.targetLabel }}<select ref="target" :value="form.target" :aria-label="`Application ${config.targetLabel.toLowerCase()}`" :disabled="status !== 'manual'" @change="editField('target', $event.target.value)"><option value="">Choose {{ config.targetLabel.toLowerCase() }}</option><option v-for="value in config.targets" :key="value">{{ value }}</option></select></label>
              <label class="app-field" :class="{ targeted: targetField === 'detail' && status === 'running' }">{{ config.detailLabel }}<select ref="detail" :value="form.detail" :aria-label="`Application ${config.detailLabel.toLowerCase()}`" :disabled="status !== 'manual'" @change="editField('detail', $event.target.value)"><option value="">Choose {{ config.detailLabel.toLowerCase() }}</option><option v-for="value in config.details" :key="value">{{ value }}</option></select></label>
              <div class="application-submit"><span>{{ status === 'manual' ? 'Make a change, then let AI continue.' : 'Changes require approval before submission.' }}</span><button ref="submit" type="button" :disabled="status !== 'approval'" @click="approve">{{ config.action }}</button></div>
            </div>
            <div v-else key="home" class="application-home">
              <p class="app-breadcrumb">{{ type === 'access' ? 'People / Overview' : 'Equipment / Overview' }}</p>
              <div class="app-overview-title"><p>{{ type === 'access' ? 'Your workspace' : 'New-starter requests' }}</p><button ref="open" type="button" :disabled="status !== 'manual'" @click="opened = true">{{ type === 'access' ? '+ Add member' : '+ New request' }}</button></div>
              <div class="app-search-placeholder"><span aria-hidden="true"><SiteIcon name="search" /></span>{{ type === 'access' ? 'Search people…' : 'Search requests…' }}</div>
              <div v-for="(person, index) in people" :key="person" class="directory-person"><span class="directory-avatar">{{ person.split(' ').map(word => word[0]).join('') }}</span><span>{{ person }}<small>{{ type === 'access' ? 'Workspace member' : 'Equipment ready' }}</small></span><span class="directory-role">{{ type === 'access' ? ['Editor', 'Viewer', 'Viewer'][index] : 'Collected' }}</span></div>
            </div>
          </Transition>

          <div v-show="status === 'running' && cursorVisible && !reducedMotion" class="agent-cursor" :style="{ transform: `translate(${cursor.x}px, ${cursor.y}px)` }" aria-hidden="true"><svg viewBox="0 0 24 28"><path d="M2 2v21l6-6 4 9 4-2-4-8h9Z" /></svg><span>AI</span></div>
        </div>
        <div class="application-footer"><span>{{ status === 'auth' ? 'Sign-in required' : 'Your existing browser session' }}</span><span>{{ status === 'complete' ? '<SiteIcon name="check" /> Saved' : 'Chrome / Edge' }}</span></div>
        </section>
        <Transition name="approval-card" appear><aside v-if="tabOpened" class="extension-card" :class="{ 'needs-decision': status === 'approval' }" aria-label="Browser extension controls">
          <div class="extension-heading"><span class="extension-symbol" aria-hidden="true"><SiteIcon name="spark" /></span><strong>Browser extension</strong><span>{{ status === 'manual' ? 'Your turn' : status === 'approval' ? 'Your decision' : ticketStatus }}</span></div>
          <div v-if="status === 'approval'" class="extension-approval" aria-label="Approve the prepared request"><p>{{ type === 'access' ? `Grant ${form.person} ${form.detail.toLowerCase()} access to ${form.target}?` : `Order a ${form.target.toLowerCase()} for ${form.person}?` }}</p><span class="approval-context">{{ type === 'access' ? 'Review the prepared action before it is submitted.' : form.detail }}</span><div><button type="button" class="lab-primary" @click="approve">Approve</button><button type="button" class="lab-secondary" @click="takeOver">Change something</button><button type="button" class="quiet-button" @click="reject">Decline</button></div></div>
          <template v-else><p class="extension-activity" aria-live="polite">{{ activity }}</p><div v-if="active" class="agent-controls"><button v-if="status === 'running'" type="button" @click="pause">Pause</button><button v-if="status === 'paused'" type="button" @click="resume">Resume AI</button><button v-if="['running', 'paused'].includes(status)" type="button" @click="takeOver">Take over</button><button v-if="status === 'manual'" type="button" @click="resume">Let AI continue</button><button type="button" class="quiet-button" @click="stop">Stop</button></div></template>
          <div class="extension-connection"><span class="agent-light" :class="{ working: status === 'running' }"></span>Cloud reasoning <span aria-hidden="true"><SiteIcon name="arrows-horizontal" /></span> This browser tab</div>
        </aside></Transition>
      </div></Transition>
    </div>
    <p class="lab-footnote">Hand over a ticket and watch the application open. Review the prepared action in the extension, then return to the dashboard for the full record.</p>
  </div>
</template>

<script>
import { browserTasks, serviceDeskTickets, nextBrowserAction, actionSignature } from '../../data/itOpsDemos';
import '../../assets/css/it-ops-labs.css';

const blankForm = () => ({ person: '', target: '', detail: '' });
export default {
  name: 'ItOpsBrowserLab',
  data() {
    return {
      tickets: serviceDeskTickets, selectedTicket: 'IT-1042', resolvedTickets: {}, tabOpened: false, type: 'access', request: { person: 'Alex Chen', target: 'Analytics', detail: 'Editor' },
      form: blankForm(), task: null, status: 'idle', signedIn: true, opened: false,
      approvedSignature: '', submitted: false, activity: 'The request is ready. Hand it over when you are.', history: [],
      targetField: '', cursor: { x: 180, y: 130 }, cursorVisible: false, reducedMotion: false,
      people: ['Morgan Liu', 'Taylor Park', 'Sam Patel'],
    };
  },
  computed: {
    config() { return browserTasks[this.type]; },
    currentTicket() { return serviceDeskTickets.find(ticket => ticket.id === this.selectedTicket); },
    ticketRecord() { return this.resolvedTickets[this.selectedTicket]; },
    visibleHistory() { return this.ticketRecord ? this.ticketRecord.history : this.history.slice(-3); },
    active() { return ['running', 'paused', 'manual', 'auth', 'approval'].includes(this.status); },
    ticketStatus() { return { idle: this.resolvedTickets[this.selectedTicket] ? 'Resolved' : 'Open', running: 'In progress', paused: 'Paused', manual: 'Your turn', auth: 'Sign-in', approval: 'Review', complete: 'Resolved', stopped: 'Stopped', declined: 'Declined' }[this.status]; },
    resultSentence() { return `${this.form.person} · ${this.form.target} · ${this.form.detail}`; },
  },
  mounted() {
    this.reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    this._onVisibility = () => { if (document.hidden && this.status === 'running') this.pause(); };
    document.addEventListener('visibilitychange', this._onVisibility);
  },
  beforeUnmount() { this._deskAnimation?.cancel(); this.clearTimer(); document.removeEventListener('visibilitychange', this._onVisibility); },
  methods: {
    clearTimer() { clearTimeout(this._timer); this._timer = null; },
    later(fn, delay = 650) { this.clearTimer(); this._timer = setTimeout(() => { if (this.status === 'running') fn(); }, this.reducedMotion ? 100 : delay); },
    eventTime() { return new Date().toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', second: '2-digit' }); },
    addHistory(text, actor = 'AI') { this.history.push({ id: this.history.length, text, actor, time: this.eventTime() }); },
    reset() { this._deskAnimation?.cancel(); this.clearTimer(); this.status = 'idle'; this.tabOpened = false; this.form = blankForm(); this.opened = false; this.submitted = false; this.approvedSignature = ''; this.history = []; this.cursorVisible = false; this.targetField = ''; this.activity = 'The request is ready. Hand it over when you are.'; },
    chooseTicket(id) { this.reset(); this.selectedTicket = id; const ticket = this.currentTicket; this.type = ticket.type; this.request = { person: ticket.person, target: ticket.target, detail: ticket.detail }; },
    viewRecord() { this.reset(); this.$nextTick(() => this.$refs.dashboard.scrollIntoView({ behavior: this.reducedMotion ? 'auto' : 'smooth', block: 'start' })); },
    begin() { this.start(); },
    start() {
      if (!this.request.person.trim() || this.active) return;
      const previousDesk = this.$refs.dashboard.getBoundingClientRect();
      this.reset(); this.task = { ...this.request, person: this.request.person.trim(), type: this.type }; this.signedIn = !this.currentTicket.requiresSignIn;
      this.tabOpened = true; this.status = 'running'; this.activity = this.type === 'access' ? `I’ll find ${this.task.person}, add them to ${this.task.target} with ${this.task.detail.toLowerCase()} access, and ask you to approve.` : `I’ll open an equipment request for ${this.task.person}, choose a ${this.task.target.toLowerCase()} and ${this.task.detail.toLowerCase()}, then bring it back for approval.`;
      this.addHistory('Handed the ticket to AI', 'You');
      this.addHistory(`Interpreted the request and opened ${this.config.app}`);
      this.$nextTick(() => {
        if (window.innerWidth < 700) this.$refs.browser.scrollIntoView({ behavior: this.reducedMotion ? 'auto' : 'smooth', block: 'start' });
        else if (!this.reducedMotion) {
          const desk = this.$refs.dashboard; const nextDesk = desk.getBoundingClientRect();
          this._deskAnimation?.cancel();
          this._deskAnimation = desk.animate([{ transform: `translateX(${previousDesk.left - nextDesk.left}px) scaleX(${previousDesk.width / nextDesk.width})` }, { transform: 'translateX(0) scaleX(1)' }], { duration: 360, easing: 'cubic-bezier(.22,1,.36,1)' });
        }
      });
      this.later(this.drive, 1700);
    },
    moveCursor(refName) {
      this.$nextTick(() => {
        const target = this.$refs[refName]; const canvas = this.$refs.canvas;
        if (!target || !canvas) return;
        const rect = target.getBoundingClientRect(); const base = canvas.getBoundingClientRect();
        this.cursor = { x: rect.left - base.left + Math.min(rect.width * 0.65, 130), y: rect.top - base.top + rect.height * 0.65 };
        this.cursorVisible = true;
      });
    },
    drive() {
      if (this.status !== 'running') return;
      const action = nextBrowserAction(this.task, this.form, this);
      this.targetField = '';
      if (action.kind === 'sign-in') { this.status = 'auth'; this.activity = 'This application needs your sign-in. I’ll wait here and continue once you’re ready.'; this.addHistory('Paused at the application sign-in screen'); this.cursorVisible = false; return; }
      if (action.kind === 'approval') { this.status = 'approval'; this.activity = 'The form is ready. Please check the person and details before I submit it.'; this.cursorVisible = false; return; }
      if (action.kind === 'complete') { this.status = 'complete'; this.activity = 'The application confirmed the request. I’ve recorded the result with this ticket.'; this.addHistory('Checked the application confirmation and resolved the ticket'); this.resolvedTickets[this.selectedTicket] = { result: this.resultSentence, completedAt: this.eventTime(), history: this.history.map(entry => ({ ...entry })) }; this.cursorVisible = false; return; }
      if (action.kind === 'open') {
        this.activity = `I’m opening the ${this.type === 'access' ? 'member form' : 'equipment form'} in the target application.`; this.moveCursor('open');
        this.later(() => { this.opened = true; this.addHistory('Opened the application form'); this.later(this.drive, 230); });
      } else if (action.kind === 'fill') {
        const labels = { person: 'colleague', target: this.config.targetLabel.toLowerCase(), detail: this.config.detailLabel.toLowerCase() };
        this.targetField = action.field; this.activity = `I’m setting the ${labels[action.field]} to ${action.value}.`; this.moveCursor(action.field);
        this.later(() => {
          if (action.field === 'person' && !this.reducedMotion) this.typeName(action.value, 0);
          else { this.form[action.field] = action.value; this.addHistory(`${labels[action.field][0].toUpperCase()}${labels[action.field].slice(1)} set to ${action.value}`); this.later(this.drive, 500); }
        }, 600);
      } else if (action.kind === 'submit') {
        this.activity = 'Your approval is recorded. I’m submitting the request and checking the confirmation.'; this.moveCursor('submit');
        this.later(() => {
          if (this.approvedSignature !== actionSignature(this.type, this.form)) { this.drive(); return; }
          this.submitted = true; this.addHistory(this.config.action === 'Grant access' ? 'Approved access submitted' : 'Approved equipment request submitted'); this.later(this.drive, 650);
        }, 800);
      }
    },
    typeName(value, index) { this.form.person = value.slice(0, index); if (index < value.length) this.later(() => this.typeName(value, index + 1), 28); else { this.addHistory(`Found ${value}`); this.later(this.drive, 400); } },
    pause() { this.clearTimer(); this.status = 'paused'; this.activity = 'Paused. The form and task are still here.'; this.addHistory('Paused the task', 'You'); },
    resume() {
      if (this.status === 'manual' && (!this.form.person.trim() || !this.form.target || !this.form.detail)) { this.activity = 'Complete the colleague and request details before handing the form back.'; return; }
      if (this.status === 'manual') { this.form.person = this.form.person.trim(); this.task.person = this.form.person; this.addHistory(`Returned the form to AI with ${this.resultSentence}`, 'You'); }
      else this.addHistory('Resumed the task', 'You');
      this.clearTimer(); this.status = 'running'; this.drive();
    },
    takeOver() { this.clearTimer(); this.status = 'manual'; this.approvedSignature = ''; this.opened = true; this.form = { ...this.task, ...Object.fromEntries(Object.entries(this.form).filter(([, value]) => value)) }; this.task = { ...this.task, ...this.form }; this.cursorVisible = false; this.activity = 'You have control. Edit the application form, then hand it back when you’re ready.'; this.addHistory('Took control of the application', 'You'); },
    editField(field, value) { if (this.status !== 'manual') return; this.form[field] = value; this.task[field] = value; this.approvedSignature = ''; },
    completeSignIn() { this.signedIn = true; this.status = 'running'; this.addHistory('Completed sign-in in the application', 'You'); this.drive(); },
    approve() { if (this.status !== 'approval') return; this.approvedSignature = actionSignature(this.type, this.form); this.addHistory(`Approved ${this.resultSentence}`, 'You'); this.status = 'running'; this.drive(); },
    reject() { this.clearTimer(); this.status = 'declined'; this.cursorVisible = false; this.approvedSignature = ''; this.activity = 'You declined the action. The request has not been submitted.'; this.addHistory('Declined the request', 'You'); },
    stop() { this.clearTimer(); this.status = 'stopped'; this.cursorVisible = false; this.approvedSignature = ''; this.activity = this.submitted ? 'The submission is recorded. Automatic follow-up has stopped.' : 'Stopped. No request was submitted.'; },
  },
};
</script>
