<template>
  <router-link :to="to" class="home-route-portal" :class="{ 'is-open': open, 'opens-up': upward }" :aria-label="label" @pointerenter="enter" @pointerleave="hovered = false" @focus="focus" @blur="focused = false">
    <span class="portal-surface">
    <span class="portal-heading">{{ title }}<ArrowUpRightIcon /></span>
    <span class="portal-description">{{ description }}</span>
    <span class="portal-scene"><HomeEntryScene :kind="kind" :active="open" /></span>
    </span>
  </router-link>
</template>

<script>
import { supportsDesktopHover, watchDesktopHover } from '../../utils/desktopHover';
import HomeEntryScene from './HomeEntryScene.vue';
import ArrowUpRightIcon from './ArrowUpRightIcon.vue';
export default {
  name: 'HomeRoutePortal',
  components: { HomeEntryScene, ArrowUpRightIcon },
  props: { to: String, kind: String, title: String, description: String, label: String },
  data: () => ({ hovered: false, focused: false, upward: false }),
  computed: { open() { return this.hovered || this.focused; } },
  mounted() { this._stopHover = watchDesktopHover(enabled => { if (!enabled) { this.hovered = false; this.focused = false; } }); },
  beforeUnmount() { this._stopHover?.(); },
  methods: {
    place(event) { this.upward = event.currentTarget.getBoundingClientRect().bottom + 80 > window.innerHeight - 16; },
    enter(event) { if (event.pointerType !== 'touch' && supportsDesktopHover()) { this.place(event); this.hovered = true; } },
    focus(event) { if (event.target.matches(':focus-visible') && supportsDesktopHover()) { this.place(event); this.focused = true; } },
  },
};
</script>

<style scoped>
.home-route-portal { position: relative; display: block; box-sizing: border-box; width: 100%; height: 110px; margin: 1rem 0; color: var(--ink, #333); text-decoration: none; -webkit-tap-highlight-color: transparent; }
.portal-surface { position: absolute; display: block; box-sizing: border-box; inset: 0 0 auto; height: 110px; padding: 20px 18px; overflow: hidden; border-block: 1px solid var(--line, #ddd); background: transparent; transition: height 420ms cubic-bezier(.22,1,.36,1), top 420ms cubic-bezier(.22,1,.36,1), background-color 180ms ease; }
.home-route-portal::after { display: none; }
.portal-heading { display: flex; align-items: center; gap: .8rem; font: 500 1rem 'Quattrocento Sans', sans-serif; }
.portal-heading :deep(svg) { width: .8rem; opacity: .45; transition: transform 350ms cubic-bezier(.22,1,.36,1), opacity 180ms ease; }
.portal-description { display: block; margin-top: 8px; width: calc(100% - 116px); max-width: 34ch; color: var(--muted, #737373); font: .78rem/1.5 'Quattrocento Sans', sans-serif; transition: opacity 150ms ease, transform 350ms cubic-bezier(.22,1,.36,1); }
.portal-scene { position: absolute; width: 138px; height: 86px; right: 2px; top: 13px; pointer-events: none; transition: width 520ms cubic-bezier(.22,1,.36,1), height 520ms cubic-bezier(.22,1,.36,1), top 520ms cubic-bezier(.22,1,.36,1), right 520ms cubic-bezier(.22,1,.36,1); }
.is-open { z-index: 4; }
.is-open .portal-surface { height: 190px; background: var(--surface, #f7f7f5); }
.is-open.opens-up .portal-surface { top: -80px; }
.is-open .portal-description { opacity: 0; transform: translateY(-6px); }
.is-open .portal-scene { width: calc(100% - 36px); height: 128px; top: 47px; right: 18px; }
.is-open .portal-heading :deep(svg) { opacity: 1; transform: translate(3px,-3px); }
.home-route-portal:focus-visible { outline: 1px solid currentColor; outline-offset: 4px; }
.home-route-portal:focus-visible :deep(*) { transition: none !important; }
@media (hover: none), (pointer: coarse), (max-width: 760px) {
  .home-route-portal { height: 110px; }
  .portal-scene { width: 110px; }
  .portal-description { width: calc(100% - 95px); }
}
@media (prefers-reduced-motion: reduce) {
  .home-route-portal, .home-route-portal * { transition: none !important; }
}
</style>
