<template>
  <div
    class="view-mode-control"
    role="group"
    :aria-label="label"
    :style="{ '--view-mode-count': visibleOptions.length, '--view-mode-index': selectedIndex }"
  >
    <span class="view-mode-thumb" aria-hidden="true"></span>
    <button
      v-for="option in visibleOptions"
      :key="option.value"
      type="button"
      class="view-mode-option"
      :class="{ selected: modelValue === option.value }"
      :aria-label="option.label"
      :title="option.label"
      :aria-pressed="(modelValue === option.value).toString()"
      @click="$emit('update:modelValue', option.value)"
    >
      <svg v-if="option.value === 'expanded'" viewBox="0 0 18 18" aria-hidden="true">
        <path d="M3.25 4.25h11.5M3.25 8.95h11.5M3.25 13.65h7.2" />
      </svg>
      <svg v-else-if="option.value === 'grid'" viewBox="0 0 18 18" aria-hidden="true">
        <rect x="3" y="3" width="4.7" height="4.7" rx=".7" />
        <rect x="10.3" y="3" width="4.7" height="4.7" rx=".7" />
        <rect x="3" y="10.3" width="4.7" height="4.7" rx=".7" />
        <rect x="10.3" y="10.3" width="4.7" height="4.7" rx=".7" />
      </svg>
      <svg v-else viewBox="0 0 18 18" aria-hidden="true">
        <path d="M3 4.25h2M7.2 4.25H15M3 9h2M7.2 9H15M3 13.75h2M7.2 13.75H15" />
      </svg>
      <span class="view-mode-label">{{ option.shortLabel }}</span>
    </button>
  </div>
</template>

<script>
export default {
  name: 'ViewModeControl',
  props: {
    modelValue: {
      type: String,
      required: true
    },
    label: {
      type: String,
      default: 'Choose a view'
    },
    allowGrid: {
      type: Boolean,
      default: true
    }
  },
  emits: ['update:modelValue'],
  data() {
    return {
      options: [
        { value: 'index', label: 'Index view', shortLabel: 'Index' },
        { value: 'grid', label: 'Grid view', shortLabel: 'Grid' },
        { value: 'expanded', label: 'Full view', shortLabel: 'Full' }
      ]
    };
  },
  computed: {
    visibleOptions() {
      return this.allowGrid ? this.options : this.options.filter((option) => option.value !== 'grid');
    },
    selectedIndex() {
      const index = this.visibleOptions.findIndex((option) => option.value === this.modelValue);
      return Math.max(0, index);
    }
  }
};
</script>

