  background: rgba(255, 255, 255, 0.82);
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06), 0 0 0 0.5px rgba(0, 0, 0, 0.035);
  transform: translateX(calc(var(--view-mode-index) * 2rem));
  pointer-events: none;
  transition: transform 210ms cubic-bezier(0.23, 1, 0.32, 1), background-color 180ms ease;
}

.view-mode-option {
  display: grid;
