  color: inherit;
  transition: color 140ms ease, background-color 140ms ease, transform 120ms cubic-bezier(0.23, 1, 0.32, 1);
}

.view-mode-option,
.view-mode-option * {
  cursor: inherit;
}

.view-mode-option.selected { color: #202022; }
.view-mode-option:active { transform: scale(0.92); }
