}

:global(body.dark-mode .view-mode-option.selected) { color: #f2f2f4; }

@media (hover: hover) and (pointer: fine) {
  :global(body.dark-mode .view-mode-option:not(.selected):hover) {
    background: rgba(255, 255, 255, 0.065);
    color: #dedee1;
  }
}

@media (max-width: 720px) {
  .view-mode-control {
    width: 100%;
